import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadAnsupaData(){const e=readFileSync(resolve(__dirname,"../../frontend/ansupa-lake-explorer/ansupa-data.js"),"utf-8");return new Function(e+"\nreturn { ANSUPA_INFO, ECOLOGY_HYDROLOGY, BIRD_FLORA_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Ansupa Lake Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadAnsupaData()}),describe("ANSUPA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.ANSUPA_INFO.id).toBe("ansupa-lake"),expect(e.ANSUPA_INFO.name).toBe("Ansupa Lake"),expect(e.ANSUPA_INFO.ramsarYear).toBe(2022),expect(e.ANSUPA_INFO.ramsarSiteNo).toBe(2487),expect(e.ANSUPA_INFO.state).toBe("Odisha")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.ANSUPA_INFO.quickStats)).toBe(!0),expect(e.ANSUPA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, oxbow hydrology, aquatic flora, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.oxbowHydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.aquaticFlora).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_FLORA_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.BIRD_FLORA_SPECIES)).toBe(!0),expect(e.BIRD_FLORA_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Cotton Pygmy Goose and Indian Sacred Lotus",()=>{const t=e.BIRD_FLORA_SPECIES.find(e=>"cotton-pygmy-goose"===e.id),a=e.BIRD_FLORA_SPECIES.find(e=>"indian-lotus"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"ansupa-lake"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../ansupa-lake-explorer/index.html")})})});